<li class="tree-node"><div class="tree-row"><span class="tree-handle">⋮⋮</span><div class="tree-name"><b>{{$item->title}}</b><small>{{$item->page?->title ?: $item->url ?: 'Без ссылки'}}</small></div><form class="tree-quick" method="post" action="{{route('admin.menus.quick',$item)}}">@csrf @method('PATCH')<select name="parent_id"><option value="">Верхний уровень</option>@foreach($all as $candidate)@if($candidate->id!==$item->id)<option value="{{$candidate->id}}" @selected($item->parent_id===$candidate->id)>{{$candidate->title}}</option>@endif @endforeach</select><input type="number" name="sort" min="0" value="{{$item->sort}}"><button>Применить</button></form><a href="{{route('admin.menus.edit',$item)}}">Настроить</a></div>@php($kids=$item->children()->with('page')->where('is_active',true)->orderBy('sort')->get())@if($kids->isNotEmpty())<ul>@foreach($kids as $child)@include('admin.menus.tree-node',['item'=>$child,'all'=>$all])@endforeach</ul>@endif</li>